import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.CuUVYbLV.js";const k=JSON.parse('{"title":"技能系统","description":"技能是什么、由谁加载、按什么顺序解析、与函数怎么分工，以及技能没有生效时如何排查","frontmatter":{"title":"技能系统","description":"技能是什么、由谁加载、按什么顺序解析、与函数怎么分工，以及技能没有生效时如何排查"},"headers":[],"relativePath":"02-Guide/skills.md","filePath":"02-Guide/skills.md"}'),l={name:"02-Guide/skills.md"};function d(n,s,o,p,c,h){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="技能系统-skill-system" tabindex="-1">技能系统（Skill System） <a class="header-anchor" href="#技能系统-skill-system" aria-label="Permalink to &quot;技能系统（Skill System）&quot;">​</a></h1><p>技能（Skill）是按需加载的知识模块：系统提示只列出技能的名称与描述，代理需要时才通过 harness 的技能工具读取正文——这就是渐进式披露（progressive disclosure，只把当下需要的信息放进上下文）。本页面向技能的使用者，说明技能放在哪、由谁加载、按什么顺序解析、什么时候不该用；要动手写一个技能，见<a href="/rolebox-docs/02-Guide/authoring-skills.html">编写技能</a>。</p><blockquote><p>相关：<a href="/rolebox-docs/02-Guide/authoring-skills.html">编写技能</a>｜<a href="/rolebox-docs/02-Guide/references.html">引用文档</a>｜<a href="/rolebox-docs/02-Guide/functions.html">函数系统</a></p></blockquote><h2 id="最小示例-给角色加一个技能" tabindex="-1">最小示例：给角色加一个技能 <a class="header-anchor" href="#最小示例-给角色加一个技能" aria-label="Permalink to &quot;最小示例：给角色加一个技能&quot;">​</a></h2><p>技能放在角色目录的 <code>skills/</code> 下，可以是一个目录（<code>{name}/SKILL.md</code>，推荐），也可以是一个单文件（<code>{name}.md</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>code-reviewer/</span></span>
<span class="line"><span>├── role.yaml</span></span>
<span class="line"><span>└── skills/</span></span>
<span class="line"><span>    └── review-checklist/</span></span>
<span class="line"><span>        └── SKILL.md</span></span></code></pre></div><p><code>skills/review-checklist/SKILL.md</code> 的正文就是给代理的指令：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review-checklist</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">代码审查清单 — 检查正确性、安全性与性能</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">审查代码时逐项确认：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 错误路径是否被处理</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 输入是否在入口处校验</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 是否存在 SQL 注入 / XSS 风险</span></span></code></pre></div><p>在 <code>role.yaml</code> 里按名称声明它：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review-checklist</span></span></code></pre></div><p>把角色同步到 harness，再检查它的状态：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，角色名、数量与路径随实际环境变化）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rolebox v1.9.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Installed Roles</span></span>
<span class="line"><span>──────────────────────────────────────────────────</span></span>
<span class="line"><span>  ✓ code-reviewer             1.0.0    (oh-my-role)  → synced</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OpenCode Integration</span></span>
<span class="line"><span>──────────────────────────────────────────────────</span></span>
<span class="line"><span>  Plugin       ✓ registered</span></span>
<span class="line"><span>  Sync target  ~/.config/opencode/rolebox</span></span>
<span class="line"><span>  Synced       1/1 roles</span></span>
<span class="line"><span>  Skill symlinks (1):</span></span>
<span class="line"><span>    ✓ all valid</span></span></code></pre></div><p><code>Synced</code> 与 <code>Skill symlinks</code> 确认的是 harness 侧能否发现技能；要在代理侧确认，直接在会话里提出一个需要该技能的问题，或让它加载 <code>review-checklist</code>。</p><h2 id="技能由谁加载" tabindex="-1">技能由谁加载 <a class="header-anchor" href="#技能由谁加载" aria-label="Permalink to &quot;技能由谁加载&quot;">​</a></h2><p>技能正文不在系统提示里。系统提示中的 <code>&lt;available_skills&gt;</code> 块只给出名称、描述、作用域与文件位置，真正的加载动作发生在 harness 一侧，而三个 harness 的通道并不相同：</p><table tabindex="0"><thead><tr><th>harness</th><th>加载通道</th><th>说明</th></tr></thead><tbody><tr><td>opencode</td><td>原生 <code>skill</code> 工具</td><td>rolebox 把角色技能镜像到 harness 的技能目录，条目名带 <code>rolebox--</code> 前缀，供 opencode 的原生技能机制发现</td></tr><tr><td>Pi</td><td><code>load_role_skill</code>（rolebox 提供，仅 Pi）</td><td>pi 0.84.2 不带 <code>skill</code> 工具，rolebox 因此补一个返回完整 SKILL.md 载荷与引用元数据的工具；宿主同时通过 <code>resources_discover</code> 获得技能路径</td></tr><tr><td>dsh</td><td>原生 <code>skill</code> 工具 + rolebox 的惰性 <code>SkillProvider</code></td><td>rolebox 向 dsh 的技能注册表注册 Provider：<code>list()</code> 只广播元数据、<code>get()</code> 才读取正文；活跃角色切换时刷新目录</td></tr></tbody></table><blockquote><p>自 v1.8.0 起，全局技能目录跟随当前 harness 的配置目录，不再是固定的 <code>~/.config/opencode/skills/</code>。</p></blockquote><p>三个通道的共同点：技能内容按需读取，不会在会话一开始就塞进上下文。</p><h2 id="声明技能" tabindex="-1">声明技能 <a class="header-anchor" href="#声明技能" aria-label="Permalink to &quot;声明技能&quot;">​</a></h2><p><code>role.yaml</code> 里有两个声明技能的字段，写法相同：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review-checklist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 角色本地技能</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">opencode_skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">humanizer</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 沿用「全局技能目录」命名的共享技能</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>skills</code></td><td>string[]</td><td>要加载的技能名列表，通常是角色目录下的技能</td></tr><tr><td><code>opencode_skills</code></td><td>string[]</td><td>要加载的技能名列表，命名保留了「来自全局技能目录」的历史约定</td></tr></tbody></table><p>两个字段会合并成同一个技能名集合，随后每个名称都走同一套四段优先级——<strong><code>skills</code> 与 <code>opencode_skills</code> 在解析行为上没有区别</strong>。子代理在自己的 <code>subagents:</code> 条目里同样支持这两个字段：技能文件优先从子代理自己的目录 <code>subagents/{slug}/skills/</code> 解析，该目录不存在时回退到角色目录。</p><h2 id="解析顺序" tabindex="-1">解析顺序 <a class="header-anchor" href="#解析顺序" aria-label="Permalink to &quot;解析顺序&quot;">​</a></h2><p>声明 <code>review-checklist</code> 之后，解析器按下面的优先级查找文件，第一个命中的胜出：</p><table tabindex="0"><thead><tr><th>优先级</th><th>候选位置</th><th>归属</th></tr></thead><tbody><tr><td>1</td><td><code>{roleDir}/skills/{name}/SKILL.md</code></td><td>角色本地，目录形式</td></tr><tr><td>2</td><td><code>{roleDir}/skills/{name}.md</code></td><td>角色本地，单文件形式</td></tr><tr><td>3</td><td><code>{globalSkillsDir}/{name}/SKILL.md</code></td><td>全局，目录形式</td></tr><tr><td>4</td><td><code>{globalSkillsDir}/{name}.md</code></td><td>全局，单文件形式</td></tr></tbody></table><p><code>{globalSkillsDir}</code> 跟随当前 harness：</p><table tabindex="0"><thead><tr><th>harness</th><th>全局技能目录</th></tr></thead><tbody><tr><td>opencode</td><td><code>$XDG_CONFIG_HOME/opencode/skills</code>，未设置时为 <code>~/.config/opencode/skills</code></td></tr><tr><td>Pi</td><td><code>$PI_CODING_AGENT_DIR/skills</code>，未设置时为 <code>~/.pi/agent/skills</code></td></tr><tr><td>dsh</td><td><code>$DSH_HOME/skills</code>，未设置时为 <code>~/.dsh/skills</code></td></tr></tbody></table><p>四个候选都没有命中时，解析器记一条日志并静默跳过这个技能名，不抛错，角色的其它技能照常加载。因此 <code>rolebox info</code> 的 <code>Skills (N)</code> 一节列出的是<strong>声明</strong>而不是解析结果：声明了但没有对应文件时，那一行仍然会出现。</p><h2 id="技能与函数的分工" tabindex="-1">技能与函数的分工 <a class="header-anchor" href="#技能与函数的分工" aria-label="Permalink to &quot;技能与函数的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>技能（Skill）</th><th>函数（Function）</th></tr></thead><tbody><tr><td>由谁触发</td><td>代理自行判断当前任务是否需要</td><td>用户在消息开头用 <code>|名称|</code> 显式激活</td></tr><tr><td>生效范围</td><td>一次加载，影响当前上下文</td><td>激活后持续生效，直到停用或会话结束</td></tr><tr><td>内容性质</td><td>参考知识、检查清单、操作指南</td><td>行为指令：阶段、门禁、状态流转</td></tr><tr><td>声明位置</td><td><code>role.yaml</code> 的 <code>skills:</code> / <code>opencode_skills:</code></td><td><code>role.yaml</code> 的 <code>functions:</code></td></tr><tr><td>参数</td><td>不支持</td><td>支持 <code>|名称:参数|</code> 与键值对</td></tr></tbody></table><p>一句话概括：<strong>技能是代理自己决定要不要读的知识，函数是用户显式激活、持续生效的行为。</strong> 函数详见<a href="/rolebox-docs/02-Guide/functions.html">函数系统</a>。</p><h2 id="什么时候不要用技能" tabindex="-1">什么时候不要用技能 <a class="header-anchor" href="#什么时候不要用技能" aria-label="Permalink to &quot;什么时候不要用技能&quot;">​</a></h2><h3 id="技能过多会稀释提示" tabindex="-1">技能过多会稀释提示 <a class="header-anchor" href="#技能过多会稀释提示" aria-label="Permalink to &quot;技能过多会稀释提示&quot;">​</a></h3><p><code>&lt;available_skills&gt;</code> 只放名称与描述，但技能一多，描述本身就构成噪声，代理也更容易选错。经验上单个角色声明的技能控制在 5–6 个以内；要判断多个技能是否重复或冲突，用 <code>skill_compose</code> 工具做一次组合分析（用法见<a href="/rolebox-docs/02-Guide/authoring-skills.html">编写技能</a>）。面向同一领域的多个技能应合并成一个。</p><h3 id="过程逻辑交给函数" tabindex="-1">过程逻辑交给函数 <a class="header-anchor" href="#过程逻辑交给函数" aria-label="Permalink to &quot;过程逻辑交给函数&quot;">​</a></h3><p>技能注入的是静态文本，没有状态、没有分支、没有执行顺序。下面这些需求应该写成函数：</p><table tabindex="0"><thead><tr><th>需求</th><th>应该用</th><th>不应该用技能</th></tr></thead><tbody><tr><td>发现诊断错误后重试</td><td>函数（条件与转移）</td><td>在 SKILL.md 里描述重试流程</td></tr><tr><td>先 plan 再 execute</td><td>函数（阶段机）</td><td>在技能里编排多个步骤</td></tr><tr><td>用户输入 <code>|review|</code> 触发审查</td><td>函数（激活语法）</td><td>在技能里定义激活语法</td></tr></tbody></table><h3 id="频繁变化的数据交给引用或记忆" tabindex="-1">频繁变化的数据交给引用或记忆 <a class="header-anchor" href="#频繁变化的数据交给引用或记忆" aria-label="Permalink to &quot;频繁变化的数据交给引用或记忆&quot;">​</a></h3><p>技能文件是静态文本，不适合存放会话状态或频繁变化的数据。按生命周期选择载体：</p><ul><li>相对静态、篇幅较长的领域知识 → 引用文档（见<a href="/rolebox-docs/02-Guide/references.html">引用文档</a>）</li><li>需要跨会话保留的决策与偏好 → <code>memory_write</code> / <code>memory_recall</code>（见<a href="/rolebox-docs/04-Advanced/memory-system.html">记忆系统</a>）</li></ul><p>函数运行期的状态由函数机制自己维护，不需要你手工管理。</p><h2 id="排查-技能没有生效" tabindex="-1">排查：技能没有生效 <a class="header-anchor" href="#排查-技能没有生效" aria-label="Permalink to &quot;排查：技能没有生效&quot;">​</a></h2><p>按下面的顺序检查，每一步排除一类原因：</p><ol><li><strong>声明是否存在</strong> —— <code>rolebox info &lt;role&gt;</code> 的 <code>Skills (N)</code> 一节列出 <code>skills:</code> 与 <code>opencode_skills:</code> 的声明值。名称必须与目录名或文件名完全一致，大小写敏感。</li><li><strong>文件是否在候选位置</strong> —— 目录形式必须叫 <code>SKILL.md</code>（大小写敏感），单文件形式必须叫 <code>{name}.md</code>；两者都先查角色本地，再查全局技能目录。</li><li><strong>harness 是否看到</strong> —— 用 <code>rolebox status</code> 看对应 target 的 <code>Skill symlinks</code>：<code>all valid</code> 表示链接目标都在；出现 <code>(broken)</code> 说明技能文件被删除或改名。</li><li><strong>解析是否失败</strong> —— 文件存在但读取失败、或 frontmatter 格式错误时，技能仍会被列出，只是描述为空。解析日志不打印到终端，而是写入日志文件：<code>ROLEBOX_LOG_FILE</code> 指定路径，否则依次尝试项目内 <code>.rolebox/logs/rolebox.log</code> 与 <code>~/.config/rolebox/logs/rolebox.log</code>；<code>ROLEBOX_LOG_LEVEL=debug</code> 提高详细度。</li><li><strong>是不是 Pi</strong> —— Pi 上的加载工具是 <code>load_role_skill</code>，不是 <code>skill</code>；让代理改用前者。</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;skill-resolver&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .rolebox/logs/rolebox.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（仅在解析器记录过日志时有输出；示例）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;0&quot;:&quot;Skill \\&quot;review-checklist\\&quot; not found. Searched:&quot;,&quot;1&quot;:{&quot;candidates&quot;:[&quot;.../skills/review-checklist/SKILL.md&quot;,&quot;.../skills/review-checklist.md&quot;]},&quot;_meta&quot;:{&quot;name&quot;:&quot;skill-resolver&quot;,&quot;logLevelName&quot;:&quot;INFO&quot;}}</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/02-Guide/authoring-skills.html">编写技能</a> —— SKILL.md 的字段、技能级引用、组合与测试</li><li><a href="/rolebox-docs/02-Guide/references.html">引用文档</a> —— 自动发现与显式声明</li><li><a href="/rolebox-docs/02-Guide/functions.html">函数系统</a> —— 用函数改变代理行为</li></ul>`,50)])])}const g=e(l,[["render",d]]);export{k as __pageData,g as default};
